const data = require('fs').readFileSync(0, 'utf8').split(/\s+/).filter(s => s.length > 0);
let ptr = 0;

const dx = [1, -1, 0, 0];
const dy = [0, 0, 1, -1];
const INF = 1000000000;

const n = parseInt(data[ptr++]);
const m = parseInt(data[ptr++]);

const a = [""];
for (let i = 1; i <= n; i++) a.push(data[ptr++]);

function ch(i, j) {
    if (i < 1 || i > n || j < 1 || j > m) return '\0';
    return a[i][j - 1];
}

let sx = 0, sy = 0, tn = 0, bn = 0;
const tx = new Array(10).fill(0), ty = new Array(10).fill(0), tp = new Array(10).fill(0);
const bx = new Array(10).fill(0), by = new Array(10).fill(0);

for (let i = 1; i <= n; i++)
    for (let j = 1; j <= m; j++) {
        const c = ch(i, j);
        if (c === 'S') { sx = i; sy = j; }
        if (c >= '0' && c <= '9') { tx[c.charCodeAt(0) - 48] = i; ty[c.charCodeAt(0) - 48] = j; tn++; }
        if (c === 'B') { bn++; bx[bn] = i; by[bn] = j; }
    }

for (let i = 1; i <= tn; i++) tp[i] = parseInt(data[ptr++]);

const T = 1 << tn;
const B = 1 << bn;
const W = m + 2;
const size = (n + 2) * W * T * B;
const f = new Int32Array(size);
f.fill(INF);

function fidx(i, j, k, l) {
    return ((i * W + j) * T + k) * B + l;
}

const qx = [], qy = [], qt = [], qb = [];
let l = 0;
qx.push(sx); qy.push(sy); qt.push(0); qb.push(0);
f[fidx(sx, sy, 0, 0)] = 0;

while (l < qx.length) {
    const ox = qx[l], oy = qy[l], ot = qt[l], ob = qb[l];
    l++;
    for (let k = 0; k < 4; k++) {
        const nx = ox + dx[k], ny = oy + dy[k];
        let nt = ot, nb = ob;
        const c = ch(nx, ny);
        if (c !== '.' && c !== 'S') continue;
        for (let i = 1; i <= tn; i++) {
            if (ny <= ty[i]) continue;
            if (nx === tx[i] - 1 && ox === tx[i]) nt ^= (1 << (i - 1));
            if (ox === tx[i] - 1 && nx === tx[i]) nt ^= (1 << (i - 1));
        }
        for (let i = 1; i <= bn; i++) {
            if (ny <= by[i]) continue;
            if (nx === bx[i] - 1 && ox === bx[i]) nb ^= (1 << (i - 1));
            if (ox === bx[i] - 1 && nx === bx[i]) nb ^= (1 << (i - 1));
        }
        const ni = fidx(nx, ny, nt, nb), oi = fidx(ox, oy, ot, ob);
        if (f[ni] > f[oi] + 1) {
            f[ni] = f[oi] + 1;
            qx.push(nx); qy.push(ny); qt.push(nt); qb.push(nb);
        }
    }
}

const pr = new Array(256).fill(0);
for (let i = 0; i < T; i++)
    for (let j = 1; j <= tn; j++)
        if (i & (1 << (j - 1))) pr[i] += tp[j];

let ans = 0;
for (let i = 0; i < T; i++)
    ans = Math.max(ans, pr[i] - f[fidx(sx, sy, i, 0)]);

console.log(ans);
